# define connected component recolor by most frequent neighbor, ignore 1 as marked overlay and test demos
import numpy as np
from collections import Counter, defaultdict

def regions_recolor(A, bg=None, tiepref=None):
 A=np.asarray(A); h,w=A.shape; seen=set(); out=A.copy(); compinfo=[]
 for r in range(h):
  for c in range(w):
   v=int(A[r,c])
   if v==1 or (r,c) in seen: continue
   st=[(r,c)]; seen.add((r,c)); cells=[]
   while st:
    x,y=st.pop(); cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and int(A[nx,ny])==v:
      seen.add((nx,ny));st.append((nx,ny))
   adj=Counter()
   for x,y in cells:
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<h and 0<=ny<w and int(A[nx,ny]) not in (v,1): adj[int(A[nx,ny])]+=1
   # any 1 touched? don't count
   if adj:
    best=max(adj.values()); choices=[k for k,vv in adj.items() if vv==best]
    repl=choices[0]
   else: repl=v
   for x,y in cells: out[x,y]=repl
   compinfo.append((v,len(cells),dict(adj),repl))
 # recolor 1s to most-common adjacent output colors
 for r,c in zip(*np.where(A==1)):
  adj=Counter(int(out[nr,nc]) for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=nr<h and 0<=nc<w)
  if adj: out[r,c]=adj.most_common(1)[0][0]
 return out,compinfo
for n,(aa,bb) in D.items():
 pred, info=regions_recolor(aa)
 print('demo',n, 'direct equality',np.mean(pred==bb), 'shapes',pred.shape,bb.shape)
 for name,t in transfs(pred).items():
  if t.shape==bb.shape: print(name,round(np.mean(t==bb),3),end='; ')
 print()
 print(info[:10])

# aggregate each color's territories through 1-bridge; recolor to dominant adjacent non-1 color

def agg_color_recolor(A):
 A=np.asarray(A); h,w=A.shape; out=A.copy(); info={}
 for v in sorted(set(A.flat)-{1}):
  cells=set(map(tuple,np.argwhere(A==v)))
  # connect same-color cells via paths through 1s only; flood from each component, allowing 1s but never other colors
  allowed={(r,c) for r in range(h) for c in range(w) if A[r,c] in (v,1)}
  seen=set(); comps=[]
  for rc in cells:
   if rc in seen: continue
   stack=[rc];seen.add(rc); component=set()
   while stack:
    x,y=stack.pop();
    if A[x,y]==v:component.add((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     p=(x+dx,y+dy)
     if p in allowed and p not in seen:seen.add(p);stack.append(p)
   if component: comps.append(component)
  # assign by neighboring non-v colors overall for component
  for comp in comps:
   adj=Counter()
   for x,y in comp:
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<h and 0<=ny<w and A[nx,ny] not in (v,1):adj[int(A[nx,ny])]+=1
   repl=adj.most_common(1)[0][0] if adj else v
   for p in comp:out[p]=repl
   info[(v,len(comp))]=(dict(adj),repl)
 # fill 1 cells with most common adjacent output
 for r,c in zip(*np.where(A==1)):
  adj=Counter(int(out[nr,nc]) for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=nr<h and 0<=nc<w)
  if adj:out[r,c]=adj.most_common()[0][0]
 return out,info
for n,(aa,bb) in D.items():
 pred,inf=agg_color_recolor(aa)
 print('demo',n,[(name,round(np.mean(t==bb),2)) for name,t in transfs(pred).items() if t.shape==bb.shape],inf)
